python
def fixedPanelsFirstQualifyingSlip(readings, k):
    a=readings
    out=[]
    s=0
    for i,x in enumerate(a):
        s+=x
        if i>=k: s-=a[i-k]
        if i>=k-1: out.append(s)
    return next((x for x in out if x>=k),-1)


java
class Solution {
  public int fixedPanelsFirstQualifyingSlip(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int s=0;for(int i=0;i<a.length;i++){s+=a[i];if(i>=k)s-=a[i-k];if(i>=k-1)out.add(s);}}
    for(int x:out)if(x>=k)return x;return -1;
  }
}
